const DEFAULT_SITE=SEED_DATA.site;
function upgradeLegacyData(db){
  if(!db||typeof db!=='object')db=clone(SEED_DATA);
  db.games=(db.games||[]).filter(g=>g.id!=='game-aynor-hanahan-2026-05-11');
  db.articles=(db.articles||[]).map(a=>{
    if(a.id==='article-welcome')return {...SEED_DATA.articles.find(x=>x.id==='article-welcome'),...a,body:a.isDemo?SEED_DATA.articles.find(x=>x.id==='article-welcome').body:a.body,status:'published',isDemo:false};
    return a;
  });
  db.site={...DEFAULT_SITE,...(db.site||{})};
  db.meta={...SEED_DATA.meta,...(db.meta||{}),edition:'2027 independent preseason edition'};
  (db.teams||[]).forEach(t=>{t.logo ||= '';t.coach ||= '';t.description ||= '';t.websiteUrl ||= '';});
  return db;
}
function publicExportData(){
  const published=clone(app.db);
  published.articles=(published.articles||[]).filter(a=>a.status!=='draft');
  published.meta={...(published.meta||{}),lastUpdated:new Date().toISOString().slice(0,10)};
  return published;
}
function safeImageUrl(value){
  if(typeof value!=='string'||!value)return '';
  if(/^data:image\/(png|jpeg|webp|gif);base64,[a-z0-9+/=]+$/i.test(value) && value.length<900000)return value;
  if(/^https?:\/\//i.test(value))return value;
  return '';
}
function safeExternalUrl(value){
  if(!value)return '';
  try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch(_){return '';}
}
function heroHTML(value){const s=String(value||DEFAULT_SITE.heroHeadline);return s.split(/\n/).slice(0,5).map(line=>esc(line).replace(/\b(region)\b/ig,'<em>$1</em>')).join('<br>');}
function splitBrandHTML(v){const parts=String(v||'Palmetto Diamond').trim().toUpperCase().split(/\s+/);const last=esc(parts.pop()||'DIAMOND');return `${esc(parts.join(''))}<span>${last}</span>`;}
function updateSiteChrome(){
 const s=app.db.site||DEFAULT_SITE;
 const accent=/^#[0-9a-f]{6}$/i.test(s.accentColor)?s.accentColor:'#ed6049';
 document.documentElement.style.setProperty('--orange',accent);
 const nav=$('.brand-copy strong');if(nav)nav.innerHTML=splitBrandHTML(s.brandName);
 const subt=$('.brand-copy small');if(subt)subt.textContent=s.brandSubtitle||'SC HIGH SCHOOL BASEBALL';
 const ribbon=$('.ribbon-inner > span:first-child');if(ribbon)ribbon.innerHTML=`<span class="pulse-dot"></span> ${esc(s.ribbon||DEFAULT_SITE.ribbon)}`;
 const foot=$('.footer-name');if(foot)foot.innerHTML=splitBrandHTML(s.brandName);
 const footText=$('.footer-inner > div:first-child p');if(footText)footText.textContent=s.footerText||DEFAULT_SITE.footerText;
 const brandMark=$('.brand-symbol');if(brandMark){const src=safeImageUrl(s.logo);if(src){brandMark.classList.add('has-brand-logo');brandMark.innerHTML=`<img src="${esc(src)}" alt="${esc(s.brandName||'Palmetto Diamond')} logo">`;}else if(brandMark.classList.contains('has-brand-logo')){brandMark.classList.remove('has-brand-logo');brandMark.innerHTML='<svg viewBox="0 0 64 64" fill="none"><path d="M32 4 60 32 32 60 4 32 32 4Z" stroke="currentColor" stroke-width="3.5"/><circle cx="32" cy="32" r="5" fill="currentColor"/></svg>';}}
 document.title=`${s.brandName||'Palmetto Diamond'} | South Carolina High School Baseball`;
}
function editorImageBlock(field,current,label){const src=safeImageUrl(current);return `<div class="field full image-input-block"><label>${esc(label)}</label><div class="image-input-row"><div class="image-preview-shell">${src?`<img class="editor-image-preview" src="${esc(src)}" alt="Current image">`:`<div class="image-placeholder editor-image-preview">No image selected</div>`}</div><div><input class="input" type="file" name="${field}" data-image-upload="true" accept="image/png,image/jpeg,image/webp,image/gif"><p class="small-note">Upload a PNG, JPG or WebP image (up to 5 MB). Automatically resized to keep hosting free. Use only images you have permission to publish.</p>${src?`<label class="check-option"><input type="checkbox" name="remove${field[0].toUpperCase()+field.slice(1)}" value="yes"> Remove current image</label>`:''}</div></div></div>`;}
async function scaledImageData(file,maxDimension=560){
 if(!file)return null;
 if(!/^image\/(png|jpeg|webp|gif)$/i.test(file.type))throw Error('Choose a PNG, JPG, WebP or GIF image.');
 if(file.size>5*1024*1024)throw Error('Image exceeds 5 MB. Choose a smaller file.');
 return new Promise((resolve,reject)=>{
  const url=URL.createObjectURL(file),im=new Image();
  im.onload=()=>{try{const scale=Math.min(1,maxDimension/Math.max(im.naturalWidth||1,im.naturalHeight||1));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.naturalWidth*scale));c.height=Math.max(1,Math.round(im.naturalHeight*scale));const ctx=c.getContext('2d');ctx.drawImage(im,0,0,c.width,c.height);const result=c.toDataURL('image/webp',.78);URL.revokeObjectURL(url);if(result.length>850000)throw Error('The compressed image is too large. Use a simpler/smaller image.');resolve(result);}catch(err){URL.revokeObjectURL(url);reject(err);}};
  im.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Could not read the image.'))};im.src=url;
 });
}
function siteForm(inline=false){const s=app.db.site||DEFAULT_SITE;return `<div class="panel editor-main-panel"><div class="panel-head"><h3>Website branding & homepage</h3><span class="subtext">Edit text, social logo and colors</span></div><div class="admin-form"><form id="site-form" class="form-grid two"><div class="field"><label>Publication name</label><input class="input" name="brandName" value="${esc(s.brandName)}" required></div><div class="field"><label>Brand subtitle</label><input class="input" name="brandSubtitle" value="${esc(s.brandSubtitle)}"></div><div class="field full"><label>Top ribbon message</label><input class="input" name="ribbon" value="${esc(s.ribbon)}"></div><div class="field"><label>Small text above main headline</label><input class="input" name="heroEyebrow" value="${esc(s.heroEyebrow)}"></div><div class="field"><label>Accent color</label><input class="input" type="color" name="accentColor" value="${esc(s.accentColor||'#ed6049')}"></div><div class="field full"><label>Homepage headline (new line = new line)</label><textarea class="input" name="heroHeadline" rows="3">${esc(s.heroHeadline)}</textarea></div><div class="field full"><label>Homepage introduction</label><textarea class="input" name="heroDescription" rows="3">${esc(s.heroDescription)}</textarea></div><div class="field full"><label>Message beside your logo</label><input class="input" name="heroCaption" value="${esc(s.heroCaption)}"></div><div class="field"><label>Stories section title</label><input class="input" name="homeNewsTitle" value="${esc(s.homeNewsTitle)}"></div><div class="field"><label>Stories section subtitle</label><input class="input" name="homeNewsSubtitle" value="${esc(s.homeNewsSubtitle)}"></div><div class="field full"><label>Footer description</label><textarea class="input" name="footerText" rows="2">${esc(s.footerText)}</textarea></div>${editorImageBlock('logo',s.logo,'Main Palmetto Diamond logo')}<div class="field full editor-button-row"><button type="submit" class="btn dark">Save website design →</button>${inline?'<button type="button" class="btn light" data-action="close-inline-edit">Cancel</button>':'<a href="#home" class="btn light">View homepage</a>'}</div></form></div></div>`;}
