async function saveSite(e){e.preventDefault();const f=new FormData(e.target),old=app.db.site||DEFAULT_SITE;
 try{const s={};for(const key of ['brandName','brandSubtitle','ribbon','heroEyebrow','heroHeadline','heroDescription','heroCaption','homeNewsTitle','homeNewsSubtitle','footerText','accentColor'])s[key]=String(f.get(key)||'').trim();if(!s.brandName)throw Error('Enter a publication name.');s.logo=old.logo||'';if(f.get('removeLogo')==='yes')s.logo='';const file=e.target.elements.logo?.files?.[0];if(file)s.logo=await scaledImageData(file,360);app.db.site={...old,...s};app.inlineEdit=null;saveDraft();toast('Homepage, branding and site logo saved in this browser.');render();}catch(err){toast(err.message||'Unable to save site design.');}}
function teamForm(t=null,inline=false){return `<div class="panel editor-main-panel"><div class="panel-head"><h3>${t?'Edit '+esc(t.name):'Add a school'}</h3><span class="subtext">School page content and logo</span></div><div class="admin-form"><form id="team-form" data-team-id="${esc(t?.id||'')}" class="form-grid two"><div class="field wide"><label>School name</label><input class="input" name="name" required value="${esc(t?.name||'')}" placeholder="e.g. Academic Magnet"></div><div class="field"><label>Mascot</label><input class="input" name="mascot" value="${esc(t?.mascot||'')}"></div><div class="field"><label>School abbreviation</label><input class="input" name="short" maxlength="4" value="${esc(t?.short||'')}"></div><div class="field"><label>Classification</label><input class="input" name="classification" required value="${esc(t?.classification||'3A')}"></div><div class="field"><label>Region</label><input class="input" name="region" value="${esc(t?.region||'')}"></div><div class="field"><label>City</label><input class="input" name="city" value="${esc(t?.city||'')}"></div><div class="field"><label>Head coach (optional)</label><input class="input" name="coach" value="${esc(t?.coach||'')}"></div><div class="field"><label>School accent color</label><input class="input" type="color" name="color" value="${esc(t?.color||'#ed6049')}"></div><div class="field full"><label>About this team / overview (optional)</label><textarea class="input" name="description" rows="5" placeholder="Write a short team overview, program history or season notes.">${esc(t?.description||'')}</textarea></div><div class="field full"><label>School athletics website (optional)</label><input class="input" type="url" name="websiteUrl" value="${esc(t?.websiteUrl||'')}" placeholder="https://"></div>${editorImageBlock('logo',t?.logo,'School/team logo')}<div class="field full editor-button-row"><button class="btn dark" type="submit">${t?'Save team page':'Add school'} →</button>${inline?'<button class="btn light" type="button" data-action="close-inline-edit">Cancel</button>':t?'<button class="btn light" type="button" data-action="cancel-team-edit">Cancel</button>':''}</div></form></div></div>`;}
