async function saveTeam(e){e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim();if(!name){toast('Please enter the school name.');return;}
 try{const id=e.target.dataset.teamId||app.teamEditingId;const t=app.db.teams.find(x=>x.id===id);const url=String(f.get('websiteUrl')||'').trim();if(url&&!safeExternalUrl(url))throw Error('Use a valid https:// or http:// athletics website URL.');const vals={name,mascot:String(f.get('mascot')||'').trim(),short:String(f.get('short')||name.slice(0,3)).trim().toUpperCase().slice(0,4),classification:String(f.get('classification')||'3A').trim(),region:String(f.get('region')||'').trim(),city:String(f.get('city')||'').trim(),coach:String(f.get('coach')||'').trim(),color:String(f.get('color')||'#ed6049'),description:String(f.get('description')||'').trim(),websiteUrl:url,logo:t?.logo||''};if(f.get('removeLogo')==='yes')vals.logo='';const file=e.target.elements.logo?.files?.[0];if(file)vals.logo=await scaledImageData(file,360);
 let dest=t;if(dest)Object.assign(dest,vals);else{let id2=slug(name);if(app.db.teams.some(x=>x.id===id2))id2=uid(id2);dest={id:id2,...vals};app.db.teams.push(dest);}
 app.teamEditingId=null;app.inlineEdit=null;saveDraft();toast('School page and logo saved. Export site data to publish publicly.');if(location.hash.startsWith('#team:'))render();else{app.adminTab='teams';render();}
 }catch(err){toast(err.message||'Could not save team page.');}}
function renderStoryBody(body){
 const parts=String(body||'').replace(/\r\n?/g,'\n').trim().split(/\n\s*\n/).filter(Boolean);
 const inline=text=>esc(text).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>');
 return parts.map(part=>{const v=part.trim();const h=/^(#{1,3})\s+([^\n]+)$/.exec(v);if(h){const level=Math.min(4,Math.max(2,h[1].length));return `<h${level}>${inline(h[2])}</h${level}>`;}if(v.split('\n').every(x=>/^[-*]\s/.test(x)))return `<ul>${v.split('\n').map(x=>`<li>${inline(x.slice(2))}</li>`).join('')}</ul>`;return `<p>${inline(v).replace(/\n/g,'<br>')}</p>`;}).join('');
}
function storyForm(a=null,inline=false){const today=new Date().toISOString().slice(0,10);return `<div class="panel editor-main-panel"><div class="panel-head"><h3>${a?'Edit existing story':'Write a new story'}</h3><span class="subtext">Newsroom · previews, reports, rankings & analysis</span></div><div class="admin-form"><form id="article-form" data-article-id="${esc(a?.id||'')}" class="form-grid two"><div class="field full"><label>Headline</label><input class="input" name="title" required value="${esc(a?.title||'')}" placeholder="2027 Team Preview: Oceanside Collegiate"></div><div class="field full"><label>Short summary (shown on cards)</label><textarea class="input" name="dek" rows="2" placeholder="One or two sentences to draw readers in.">${esc(a?.dek||'')}</textarea></div><div class="field"><label>Category</label><select class="input" name="category">${['Team Preview','Breaking News','Game Recap','Scouting Report','Rankings','Feature','Recruiting','Analysis','Other'].map(v=>`<option value="${v}" ${(a?.category||'Team Preview')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Article status</label><select class="input" name="status"><option value="draft" ${a?.status==='draft'||!a?'selected':''}>Private browser draft</option><option value="published" ${a?.status!=='draft'&&a?'selected':''}>Ready for public publishing</option></select></div><div class="field"><label>Byline</label><input class="input" name="author" value="${esc(a?.author||'Palmetto Diamond Staff')}"></div><div class="field"><label>Date</label><input class="input" type="date" name="date" value="${esc(a?.date||today)}"></div><div class="field full"><label>Associated school (optional)</label><select class="input" name="teamId"><option value="">Statewide / No team</option>${teamOptions(a?.teamId||app.storyTeamPrefill||'')}</select></div><div class="field full"><label>Article body</label><textarea class="input story-body-input" name="body" rows="17" required placeholder="Write your article. Blank lines separate paragraphs. Start headings with ## and bold text with **double asterisks**.">${esc(a?.body||'')}</textarea><p class="small-note">Supports paragraphs, ## headings, **bold**, *italic* and - bullet points. All story text is escaped for safe display.</p></div>${editorImageBlock('coverImage',a?.coverImage,'Story cover image (optional)')}<div class="field full editor-button-row"><button class="btn dark" type="submit">${a?'Save changes':'Save story'} →</button>${inline?'<button type="button" class="btn light" data-action="close-inline-edit">Cancel</button>':'<a href="#articles" class="btn light">View stories</a>'}</div></form></div></div>`;}
function adminArticles(){const current=app.db.articles.find(a=>a.id===app.adminArticleEditId),rows=orderedArticles(true);return `${storyForm(current,false)}<div class="panel" style="margin-top:20px"><div class="panel-head"><h3>Manage your stories</h3><button class="btn sm dark" data-action="new-story">+ New story</button></div><div class="editor-row-list panel-pad">${rows.map(a=>`<div class="editor-list-row story-editor-row"><span class="editor-story-icon">${a.coverImage?`<img src="${esc(safeImageUrl(a.coverImage))}" alt="" loading="lazy">`:'✍'}</span><span class="editor-list-copy"><strong>${esc(a.title)}</strong><br><small>${fmtDate(a.date,'short')} · ${esc(a.category||'Story')} · <b>${a.status==='draft'?'PRIVATE DRAFT':'READY TO PUBLISH'}</b></small></span><button type="button" class="btn sm light" data-action="admin-edit-story" data-id="${esc(a.id)}">Edit</button><a class="btn sm light" href="#article:${esc(a.id)}">Preview</a><button type="button" class="btn sm light danger" data-action="delete-story" data-id="${esc(a.id)}">Delete</button></div>`).join('')||'<div class="empty">No stories saved yet. Start with your next team preview.</div>'}</div><div class="panel-pad small-note">Draft stories are saved only in your browser and excluded from the public publishing file. Use the private backup download to protect them.</div></div>`;}
async function saveArticle(e){e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')||'').trim(),body=String(f.get('body')||'').trim();if(!title||!body){toast('Add a headline and story body.');return;}
 try{const id=e.target.dataset.articleId||app.adminArticleEditId;const a=app.db.articles.find(x=>x.id===id);const item={title,body,dek:String(f.get('dek')||'').trim(),category:String(f.get('category')||'Team Preview'),status:f.get('status')==='published'?'published':'draft',author:String(f.get('author')||'Palmetto Diamond Staff').trim(),date:String(f.get('date')||new Date().toISOString().slice(0,10)),teamId:String(f.get('teamId')||''),coverImage:a?.coverImage||''};if(f.get('removeCoverImage')==='yes')item.coverImage='';const file=e.target.elements.coverImage?.files?.[0];if(file)item.coverImage=await scaledImageData(file,1100);let saved=a;if(a)Object.assign(a,item);else{saved={id:uid('article'),...item};app.db.articles.push(saved);}app.adminArticleEditId=null;app.storyTeamPrefill=null;app.inlineEdit=null;saveDraft();toast(item.status==='draft'?'Private browser draft saved.':'Story saved! Export the public file to publish it online.');setRoute(`#article:${encodeURIComponent(saved.id)}`);}
 catch(err){toast(err.message||'Unable to save story.');}}
function renderArticles(){const arts=orderedArticles();return `${pageHeading('Stories from the diamond','Team previews, original reporting, scouting analysis, and the region races that matter.',`<button type="button" class="btn dark" data-action="new-story">+ Write a story</button>`)}<div class="quick-edit-wrap"><button type="button" class="btn sm light" data-action="manage-stories">✎ Manage all stories</button></div><div class="article-cards">${arts.map((a,i)=>`<a class="article-card" href="#article:${esc(a.id)}"><div class="article-thumb">${safeImageUrl(a.coverImage)?`<img class="story-cover-thumb" src="${esc(safeImageUrl(a.coverImage))}" alt="" loading="lazy">`:''}<span>${esc(a.category||'Feature')}</span>${a.coverImage?'':`<strong class="big-number">${String(i+1).padStart(2,'0')}</strong>`}</div><div class="article-card-content"><span class="meta">${esc(a.category||'Story')} · ${fmtDate(a.date)}</span><h3>${esc(a.title)}</h3><p>${esc(a.dek||'')}</p><span class="see-all">Read story ↗</span></div></a>`).join('')||'<div class="panel empty">No published stories yet. Use “Write a story” to create your first article.</div>'}</div>`;}
function renderArticle(id){const a=app.db.articles.find(x=>x.id===id);if(!a)return '<div class="panel empty">Story not found.</div>';const img=safeImageUrl(a.coverImage);return `<div class="reading-width"><a href="#articles" class="back-link">← Back to stories</a><div class="quick-edit-wrap"><button class="btn sm light" type="button" data-action="inline-edit-story" data-id="${esc(a.id)}">✎ Edit this story</button><button class="btn sm light" type="button" data-action="admin-edit-story" data-id="${esc(a.id)}">Open newsroom</button><button class="btn sm light danger" type="button" data-action="delete-story" data-id="${esc(a.id)}">Delete</button></div>${app.inlineEdit?.page==='article'&&app.inlineEdit.id===id?`<div class="inline-edit-shell"><div class="inline-edit-label">EDIT STORY · SAVES TO THIS BROWSER</div>${storyForm(a,true)}</div>`:''}${a.status==='draft'?'<div class="info-band warning">PRIVATE BROWSER DRAFT — not included in the public website export.</div>':''}<div class="article-hero"><span class="eyebrow">${esc(a.category||'Story')} · ${fmtDate(a.date)}</span><h1>${esc(a.title)}</h1><p>${esc(a.dek||'')}</p><small style="color:#c4cdd8">By ${esc(a.author||'Palmetto Diamond Staff')}</small></div>${img?`<img class="story-hero-image" src="${esc(img)}" alt="Cover image for ${esc(a.title)}">`:''}<div class="article-body">${renderStoryBody(a.body)}</div>${a.teamId?`<a href="#team:${esc(a.teamId)}" class="btn light">View ${esc(team(a.teamId).name)} team page ↗</a>`:''}</div>`;}
function adminGameList(){const games=orderedGames(app.db.games);return `<div class="panel"><div class="panel-head"><h3>Games in database</h3><button class="btn sm light" data-action="new-game">+ New</button></div><div class="editor-row-list panel-pad">${games.map(g=>`<div class="editor-list-row"><span class="editor-list-copy"><strong>${esc(team(g.awayId).name)} ${g.awayScore??'—'} – ${esc(team(g.homeId).name)} ${g.homeScore??'—'}</strong><br><small>${fmtDate(g.date,'short')} · ${esc(g.season||'')}</small></span><button type="button" class="btn sm light" data-action="edit-game" data-id="${esc(g.id)}">Edit</button><button type="button" class="btn sm light danger" data-action="delete-game" data-id="${esc(g.id)}">Delete</button></div>`).join('')||'<div class="empty">No games in the database. The old Hanahan–Aynor demo game has been removed.</div>'}</div></div>`;}
// Editors accessible directly on public-facing pages; updates are still browser-local.
document.addEventListener('click',event=>{
 const el=event.target.closest('[data-action]');if(!el)return;
 const action=el.dataset.action;
 if(action==='inline-edit-site'){event.preventDefault();app.inlineEdit=app.inlineEdit?.page==='site'?null:{page:'site'};render();window.scrollTo({top:0,behavior:'instant'});}
 else if(action==='inline-edit-team'){event.preventDefault();app.inlineEdit=app.inlineEdit?.page==='team'&&app.inlineEdit.id===el.dataset.id?null:{page:'team',id:el.dataset.id};render();window.scrollTo({top:0,behavior:'instant'});}
 else if(action==='inline-edit-story'){event.preventDefault();app.inlineEdit=app.inlineEdit?.page==='article'&&app.inlineEdit.id===el.dataset.id?null:{page:'article',id:el.dataset.id};render();window.scrollTo({top:0,behavior:'instant'});}
 else if(action==='close-inline-edit'){event.preventDefault();app.inlineEdit=null;render();}
 else if(action==='open-team-roster'){event.preventDefault();app.adminRosterTeamId=el.dataset.id;app.adminRosterEditId=null;app.adminTab='roster';app.inlineEdit=null;setRoute('#admin');}
 else if(action==='new-team-story'){event.preventDefault();app.storyTeamPrefill=el.dataset.id;app.adminArticleEditId=null;app.adminTab='articles';app.inlineEdit=null;setRoute('#admin');}
 else if(action==='new-story'){event.preventDefault();app.adminArticleEditId=null;app.storyTeamPrefill=null;app.adminTab='articles';app.inlineEdit=null;setRoute('#admin');}
 else if(action==='manage-stories'){event.preventDefault();app.adminTab='articles';app.adminArticleEditId=null;app.inlineEdit=null;setRoute('#admin');}
 else if(action==='admin-edit-story'){event.preventDefault();app.adminArticleEditId=el.dataset.id;app.adminTab='articles';app.inlineEdit=null;setRoute('#admin');}
 else if(action==='delete-story'){event.preventDefault();const a=app.db.articles.find(x=>x.id===el.dataset.id);if(a&&confirm(`Delete "${a.title}"? This removes it from the browser draft.`)){app.db.articles=app.db.articles.filter(x=>x.id!==a.id);app.inlineEdit=null;app.adminArticleEditId=null;saveDraft();toast('Story deleted from your browser draft.');if(location.hash.startsWith('#article:'))setRoute('#articles');else render();}}
 else if(action==='delete-game'){event.preventDefault();const g=app.db.games.find(x=>x.id===el.dataset.id);if(g&&confirm('Delete this game and its player statistics from your browser draft?')){app.db.games=app.db.games.filter(x=>x.id!==g.id);saveDraft();toast('Game deleted. Standings and statistics recalculated.');render();}}
 else if(action==='export-backup'){event.preventDefault();downloadFile('palmetto-diamond-private-backup.json',JSON.stringify(app.db,null,2));toast('Full backup downloaded, including private drafts. Do not publish that backup.');}
},false);
