document.addEventListener('change',e=>{
 const el=e.target;if(!el.matches('input[data-image-upload]')||!el.files?.[0])return;
 const form=el.closest('form');const holder=el.closest('.image-input-block')?.querySelector('.image-preview-shell');if(!holder)return;
 const file=el.files[0];if(!/^image\/(png|jpeg|webp|gif)$/i.test(file.type)){toast('Choose a PNG, JPG, WebP or GIF image.');return;}
 const url=URL.createObjectURL(file),img=document.createElement('img');img.className='editor-image-preview';img.alt='New image preview';img.onload=()=>URL.revokeObjectURL(url);img.src=url;holder.replaceChildren(img);
});
